import type { CanvassingState } from '~/client';
import type { AlertVariants } from '~/components/ui/alert';

type StateDescription = {
  description: string;
  variant: NonNullable<AlertVariants['variant']>;
};

export const canvassingStateDescriptions: Record<CanvassingState, StateDescription> = {
  pending_audio: { description: 'Waiting for note data', variant: 'info' },
  ready_for_processing: { description: 'Notes received, ready for processing', variant: 'info' },
  unrefined: { description: 'Initial note processing complete', variant: 'info' },
  refined: { description: 'Note refinement complete', variant: 'info' },
  diarized: { description: 'Speaker diarization complete', variant: 'info' },
  evidence_extracted: { description: 'Evidence extraction complete', variant: 'info' },
  done: { description: 'Processing complete', variant: 'success' },
  timed_out: { description: 'Note data was not received in time', variant: 'warning' },
  failed: { description: 'Processing failed', variant: 'destructive' },
};

export function getCanvassingStateDescription(state: CanvassingState): StateDescription {
  return canvassingStateDescriptions[state] ?? { description: snakeCaseToCapitalizedCase(state), variant: 'default' };
}
