import type { VoiceVerificationState } from '~/client';
import type { AlertVariants } from '~/components/ui/alert';

type StateDescription = {
  description: string;
  variant: NonNullable<AlertVariants['variant']>;
};

export const voiceVerificationStateDescriptions: Record<VoiceVerificationState, StateDescription> = {
  new: { description: 'New signatory verification', variant: 'info' },
  in_progress: { description: 'Signatory verification in progress', variant: 'info' },
  ready_for_submit: { description: 'Ready for submission', variant: 'info' },
  ready_for_processing: { description: 'Submitted, ready for processing', variant: 'info' },
  processing: { description: 'Processing signatory verification', variant: 'info' },
  completed: { description: 'Signatory verification completed', variant: 'success' },
  canceled: { description: 'Signatory verification was canceled', variant: 'warning' },
  failed: { description: 'Signatory verification failed', variant: 'destructive' },
};

export function getVoiceVerificationStateDescription(state: VoiceVerificationState): StateDescription {
  return (
    voiceVerificationStateDescriptions[state] ?? { description: snakeCaseToCapitalizedCase(state), variant: 'default' }
  );
}
