<template>
  <section class="grid grid-cols-1 gap-6">
    <PageTitle title="Conversation Details" />
    <div class="flex flex-wrap justify-between items-center gap-4">
      <GoBackButton v-if="conversation?.project_id" subject="conversations" :fallback-to="{ name: 'conversations' }" />
      <Badge v-if="conversation?.status" :variant="getConversationStatusBadge(conversation.status).variant">
        {{ getConversationStatusBadge(conversation.status).label }}
      </Badge>
    </div>
    <AppLoader v-if="isLoading" subject="conversation details" />
    <AppError v-else-if="error" :error="error" title="Failed to load conversation details" />
    <AppEmpty v-else-if="!conversation" subject="conversation details" />
    <ConversationDetails v-else :data="conversation" />
  </section>
</template>

<script setup lang="ts">
import { getConversationDetails } from '~/client';
import { getConversationStatusBadge } from '~/constants/conversations/conversationStatuses';

useHead({
  title: 'Conversation Details',
});

const route = useRoute('conversations-id');
const conversationId = computed(() => route.params.id?.toString() || '');

const {
  data: conversation,
  error,
  isLoading,
} = useQuery({
  key: () => ['conversation-details', conversationId.value],
  query: () => getConversationDetails({ composable: '$fetch', path: { conversation_id: conversationId.value } }),
  staleTime: 0,
  enabled: computed(() => !!conversationId.value && route.name === 'conversations-id'),
});
</script>
