<template>
  <Alert v-if="stateInfo" :variant="stateInfo.variant">
    <component :is="stateIcon" class="size-5" />
    <AlertTitle>{{ typeLabel }}</AlertTitle>
    <AlertDescription>{{ stateInfo.description }}</AlertDescription>
  </Alert>

  <Card>
    <CardContent class="flex flex-col gap-4">
      <div class="grid grid-cols-1 sm:grid-cols-2 gap-2 sm:gap-4">
        <LabeledEntityUser :user-id="data.user_id" />
        <LabeledEntityProject :project-id="data.project_id" />
        <LabeledEntityDate label="Created At" :date="data.created_at" />
        <LabeledEntityDate label="Updated At" :date="data.updated_at" />
        <LabeledValueIcon label="Duration" :value="formatDuration(data.duration)" :icon="TimerIcon" />
        <LabeledValueIcon label="Validity" :value="data.validity ?? 'N/A'" :icon="ShieldCheckIcon" />
        <LabeledValueIcon label="Type" :value="typeLabel" :icon="MessageSquareIcon" />
      </div>
    </CardContent>
  </Card>

  <Card v-if="data.type === 'canvassing' && (data.evaluation_cqi != null || data.evaluation_compliant != null)">
    <CardHeader>
      <CardTitle>Evaluation</CardTitle>
    </CardHeader>
    <CardContent class="flex flex-col gap-4">
      <div class="grid grid-cols-1 sm:grid-cols-2 gap-2 sm:gap-4">
        <LabeledValueIcon
          v-if="data.evaluation_cqi != null"
          label="CQI Score"
          :value="data.evaluation_cqi.toFixed(1)"
          :icon="GaugeIcon"
        />
        <LabeledValueIcon
          v-if="data.evaluation_compliant != null"
          label="Compliant"
          :value="data.evaluation_compliant ? 'Yes' : 'No'"
          :icon="ShieldCheckIcon"
        />
      </div>
      <template v-if="data.evaluation_scores">
        <Separator />
        <div class="grid grid-cols-1 md:grid-cols-2 gap-4 sm:gap-8">
          <div class="grid grid-cols-3 gap-2">
            <h3 class="text-lg font-medium col-span-3">Category Scores</h3>
            <span class="col-span-2">Communication</span>
            <p class="px-4 col-span-1">{{ formatScore(data.evaluation_scores.categories.communication) }}</p>
            <span class="col-span-2">Compliance</span>
            <p class="px-4 col-span-1">{{ formatScore(data.evaluation_scores.categories.compliance) }}</p>
            <span class="col-span-2">Efficiency</span>
            <p class="px-4 col-span-1">{{ formatScore(data.evaluation_scores.categories.efficiency) }}</p>
          </div>
          <div class="grid grid-cols-3 gap-2">
            <h3 class="text-lg font-medium col-span-3">Extra Scores</h3>
            <span class="col-span-2">Politeness</span>
            <p class="px-4 col-span-1">{{ formatScore(data.evaluation_scores.micro.politeness) }}</p>
            <span class="col-span-2">Engagement</span>
            <p class="px-4 col-span-1">{{ formatScore(data.evaluation_scores.micro.engagement) }}</p>
            <span class="col-span-2">Objection</span>
            <p class="px-4 col-span-1">{{ formatScore(data.evaluation_scores.micro.objection) }}</p>
            <span class="col-span-2">Operational Effectiveness</span>
            <p class="px-4 col-span-1">{{ formatScore(data.evaluation_scores.micro.resilience) }}</p>
            <span class="col-span-2">Identity</span>
            <p class="px-4 col-span-1">{{ formatScore(data.evaluation_scores.micro.identity) }}</p>
            <span class="col-span-2">Safety</span>
            <p class="px-4 col-span-1">{{ formatScore(data.evaluation_scores.micro.safety) }}</p>
            <span class="col-span-2">Pacing</span>
            <p class="px-4 col-span-1">{{ formatScore(data.evaluation_scores.micro.pacing) }}</p>
            <span class="col-span-2">Duration</span>
            <p class="px-4 col-span-1">{{ formatScore(data.evaluation_scores.micro.duration) }}</p>
          </div>
        </div>
      </template>
    </CardContent>
  </Card>

  <Card v-if="data.audio_url && isAdmin">
    <CardHeader>
      <CardTitle>Notes</CardTitle>
    </CardHeader>
    <CardContent>
      <audio ref="audioEl" controls class="w-full" @timeupdate="onTimeUpdate">
        <source :src="data.audio_url" />
      </audio>
    </CardContent>
  </Card>

  <Card v-if="data.dialog_final && data.dialog_final.utterances.length > 0">
    <CardHeader>
      <CardTitle>Transcript</CardTitle>
    </CardHeader>
    <CardContent class="flex max-h-[28rem] flex-col gap-3 overflow-y-auto">
      <div
        v-for="(utterance, index) in data.dialog_final.utterances"
        :key="index"
        :ref="(el) => setRowRef(el as HTMLElement | null, index)"
        :class="rowClass(index)"
        @click="isAdmin && seekTo(utterance.start)"
      >
        <div class="flex items-center justify-between">
          <span class="text-sm font-medium capitalize text-accent-foreground">{{ utterance.speaker_id }}</span>
          <span class="text-xs text-muted-foreground">
            {{ formatTimestamp(utterance.start) }} – {{ formatTimestamp(utterance.end) }}
          </span>
        </div>
        <p class="text-sm">{{ utterance.text }}</p>
      </div>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue';
import type { ConversationDetailsResponse } from '~/client';
import { Alert, AlertTitle, AlertDescription } from '~/components/ui/alert';
import LabeledEntityUser from '~/components/common/labeled-entity/LabeledEntityUser.vue';
import LabeledEntityProject from '~/components/common/labeled-entity/LabeledEntityProject.vue';
import LabeledEntityDate from '~/components/common/labeled-entity/LabeledEntityDate.vue';
import LabeledValueIcon from '~/components/common/LabeledValueIcon.vue';
import {
  TimerIcon,
  ShieldCheckIcon,
  GaugeIcon,
  MessageSquareIcon,
  InfoIcon,
  CheckCircle2Icon,
  AlertTriangleIcon,
  XCircleIcon,
} from 'lucide-vue-next';
import { getCanvassingStateDescription } from '~/constants/conversations/canvassingStateDescriptions';
import { getVoiceVerificationStateDescription } from '~/constants/conversations/voiceVerificationStateDescriptions';

const props = defineProps<{
  data: ConversationDetailsResponse;
}>();

const { isAdmin } = useUserRole();

const audioEl = ref<HTMLAudioElement | null>(null);
const rowEls = ref<(HTMLElement | null)[]>([]);
const currentTime = ref(0);

const utterances = computed(() => props.data.dialog_final?.utterances ?? []);
const audioOffset = computed(() => props.data.audio_offset_seconds ?? 0);

const activeIndex = computed(() => {
  const position = currentTime.value + audioOffset.value;
  return utterances.value.findIndex((u) => position >= u.start && position < u.end);
});

function onTimeUpdate(event: Event) {
  currentTime.value = (event.target as HTMLAudioElement).currentTime;
}

function setRowRef(el: HTMLElement | null, index: number) {
  rowEls.value[index] = el;
}

function rowClass(index: number) {
  const showInteractive = isAdmin.value;
  const isActive = index === activeIndex.value && showInteractive;
  return [
    'flex flex-col gap-1 rounded-lg border p-3 transition-colors',
    showInteractive && 'cursor-pointer',
    isActive ? 'border-primary bg-primary/10' : showInteractive && 'hover:bg-accent/50',
  ];
}

function seekTo(start: number) {
  const audio = audioEl.value;
  if (!audio) return;
  audio.currentTime = Math.max(0, start - audioOffset.value);
  void audio.play();
}

watch(activeIndex, async (index) => {
  if (index < 0) return;
  await nextTick();
  rowEls.value[index]?.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
});

const typeLabel = computed(() => {
  return props.data.type === 'canvassing' ? 'Canvassing' : 'Signatory Verification';
});

const stateInfo = computed(() => {
  if (props.data.type === 'canvassing' && props.data.canvassing_state) {
    return getCanvassingStateDescription(props.data.canvassing_state);
  }
  if (props.data.type === 'voice_verification' && props.data.voice_verification_state) {
    return getVoiceVerificationStateDescription(props.data.voice_verification_state);
  }
  return null;
});

const stateIcon = computed(() => {
  if (!stateInfo.value) return InfoIcon;
  switch (stateInfo.value.variant) {
    case 'success':
      return CheckCircle2Icon;
    case 'warning':
      return AlertTriangleIcon;
    case 'destructive':
      return XCircleIcon;
    default:
      return InfoIcon;
  }
});

function formatDuration(seconds: number | null): string {
  if (seconds == null) return 'N/A';
  const mins = Math.floor(seconds / 60);
  const secs = Math.round(seconds % 60);
  if (mins === 0) return `${secs}s`;
  return `${mins}m ${secs}s`;
}

function formatScore(score: number | null): string {
  if (score == null) return 'N/A';
  return score.toFixed(1);
}

function formatTimestamp(seconds: number): string {
  const mins = Math.floor(seconds / 60);
  const secs = Math.floor(seconds % 60);
  return `${mins}:${secs.toString().padStart(2, '0')}`;
}
</script>
